import { useState } from "react"
import { createRoot } from "react-dom/client"

const dishes = [
  { id: 1, name: "Party jollof", price: 3500 },
  { id: 2, name: "Pepper soup", price: 3000 },
  { id: 3, name: "Zobo (50cl)", price: 700 },
]

function MenuList({ dishes, onAdd }) {
  return dishes.map((d) => <button key={d.id} onClick={() => onAdd(d)}>Add {d.name}</button>)
}

function Cart({ cart, onChangeQty }) {
  return (
    <ul className="cart">
      {cart.map((i) => (
        <li key={i.id}>
          <span>{i.name} × {i.qty}</span>{" "}
          <button onClick={() => onChangeQty(i.id, -1)}>−</button>
          <button onClick={() => onChangeQty(i.id, 1)}>+</button>
        </li>
      ))}
    </ul>
  )
}

function CartSummary({ cart }) {
  const plates = cart.reduce((n, i) => n + i.qty, 0)
  const total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)
  return <p className="summary">{plates} plates · ₦{total.toLocaleString()}</p>
}

function App() {
  const [cart, setCart] = useState([])

  function add(dish) {
    setCart((c) =>
      c.some((i) => i.id === dish.id)
        ? c.map((i) => (i.id === dish.id ? { ...i, qty: i.qty + 1 } : i))
        : [...c, { ...dish, qty: 1 }],
    )
  }

  function changeQty(id, delta) {
    setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: i.qty + delta } : i)).filter((i) => i.qty > 0))
  }

  return (
    <>
      <MenuList dishes={dishes} onAdd={add} />
      <Cart cart={cart} onChangeQty={changeQty} />
      <CartSummary cart={cart} />
    </>
  )
}

createRoot(document.getElementById("root")).render(<App />)
